import{c as a,ao as t,ah as h,L as l,O as d,I as i,Q as n,aY as p,P as o}from"./chunks/framework.YKVbmyBD.js";const f=JSON.parse('{"title":"用户及其权限管理","description":"","frontmatter":{},"headers":[],"relativePath":"fovlin-notes/linux-guide/configure-system/user-manage.md","filePath":"fovlin-notes/linux-guide/configure-system/user-manage.md"}'),r={name:"fovlin-notes/linux-guide/configure-system/user-manage.md"};function k(c,s,g,b,u,F){const e=t("center");return h(),l("div",null,[s[1]||(s[1]=d('<h1 id="用户及其权限管理" tabindex="-1">用户及其权限管理 <a class="header-anchor" href="#用户及其权限管理" aria-label="Permalink to “用户及其权限管理”">​</a></h1><p>在 Linux 中正确配置用户与文件权限，能够提升系统安全性。</p><h2 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to “用户管理”">​</a></h2><h3 id="创建新用户" tabindex="-1">创建新用户 <a class="header-anchor" href="#创建新用户" aria-label="Permalink to “创建新用户”">​</a></h3><p>一般地，大部分发行版在安装完成后，会为你自动创建好一个新用户，但如果你需要创建一个新用户，可以使用 <code>useradd</code> 进行创建。</p><p>格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>useradd [参数] 用户名</span></span></code></pre></div><p><code>useradd</code> 命令的参数如下：</p><table tabindex="0"><thead><tr><th>参数</th><th>描述</th><th>默认值</th></tr></thead><tbody><tr><td>-d</td><td>指定用户主目录</td><td>/home/用户名</td></tr><tr><td>-g</td><td>指定用户所属组</td><td>用户名本身</td></tr><tr><td>-m</td><td>如果没有家目录，自动创建用户主目录</td><td>-</td></tr><tr><td>-s</td><td>指定用户登录shell</td><td>因发行版而异</td></tr></tbody></table><p>例如创建一个名为 linux 的用户，将 <code>/home/linux</code> 用户主目录，并使用 <code>/bin/bash</code> 作为用户登录shell。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">useradd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -md</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/linux</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /bin/bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux</span></span></code></pre></div><p>创建完成后，可以使用 <code>passwd + 用户名</code> 命令设置密码。</p><h3 id="管理用户" tabindex="-1">管理用户 <a class="header-anchor" href="#管理用户" aria-label="Permalink to “管理用户”">​</a></h3><p>系统中记录用户信息的文件位于 <code>/etc/passwd</code>，每行都会代表一个用户，其中不少为系统内部用户，不建议对此类用户进行操作。</p><p>文件内一行内容如下：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fovlin:x:1000:1000:user:/home/fovlin:/bin/bash</span></span></code></pre></div><hr><p><code>用户名</code> <code>密码（不存处于此）</code> <code>用户ID:UID</code> <code>用户组ID:GID</code> <code>描述信息</code> <code>家目录位置</code> <code>用户默认 Shell</code></p><hr><p>使用 <code>usermod</code> 命令对用户进行管理。</p><p>格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>usermod [参数] 用户名</span></span></code></pre></div><p><code>usermod</code> 命令的参数如下：</p><table tabindex="0"><thead><tr><th>参数</th><th>描述</th></tr></thead><tbody><tr><td>-d</td><td>修改用户主目录</td></tr><tr><td>-g</td><td>修改用户所属组</td></tr><tr><td>-G</td><td>修改用户的附属组</td></tr><tr><td>-s</td><td>修改用户shell</td></tr></tbody></table><p>例如将用户 <code>linux</code> 的主目录修改为 <code>/home/linuxos/</code>，并修改用户 <code>linux</code> 的登录shell为 <code>/bin/sh</code>。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/linuxos/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /bin/sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux</span></span></code></pre></div><h3 id="删除用户" tabindex="-1">删除用户 <a class="header-anchor" href="#删除用户" aria-label="Permalink to “删除用户”">​</a></h3><p>使用 <code>userdel</code> 命令删除用户。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">userdel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 用户名</span></span></code></pre></div><p>或使用 <code>userdel -r</code> 命令删除用户，并删除用户主目录。</p><h3 id="用户组" tabindex="-1">用户组 <a class="header-anchor" href="#用户组" aria-label="Permalink to “用户组”">​</a></h3><p>使用以下命令添加用户组：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">groupadd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span></span></code></pre></div><p>查询用户所在的组：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">groups</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> username</span></span></code></pre></div><p>例如以下输出：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fovlin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fovlin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wheel</span></span></code></pre></div><p>表示用户 <code>fovlin</code> 的主组是 <code>fovlin</code>，其附属组为 <code>wheel</code>。</p><p>要更改用户所在组，使用 <code>usermod -G groupname username</code> 来更改用户的附属组，使用 <code>usermod -g groupname username</code> 来更改用户的主组。</p><h3 id="更改文件所有者" tabindex="-1">更改文件所有者 <a class="header-anchor" href="#更改文件所有者" aria-label="Permalink to “更改文件所有者”">​</a></h3><p>使用 <code>chown</code> 可以改变文件权限，用法如下：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [选项] 用户名:用户组 文件名</span></span></code></pre></div><p>例如将文件 script.sh 所有者改为 fovlin 执行以下命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fovlin:fovlin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.sh</span></span></code></pre></div><blockquote><p>并非文件所有者，需要超级管理员权限进行操作。</p></blockquote><p>例如将目录 docs 的所有者递归改为 fovlin，执行以下命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fovlin:fovlin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span></code></pre></div><br><br><br>',50)),i("p",null,[i("em",null,[i("strong",null,[n(e,null,{default:p(()=>[...s[0]||(s[0]=[o("--- 由 柏茯灵_RsDline 编写 ---",-1)])]),_:1})])])])])}const C=a(r,[["render",k]]);export{f as __pageData,C as default};
